import adsk.core, adsk.fusion, json
def p(x,y): return adsk.core.Point3D.create(x,y,0)
def rectangle(sk,x0,y0,x1,y1):
    ls=sk.sketchCurves.sketchLines
    ls.addByTwoPoints(p(x0,y0),p(x1,y0)); ls.addByTwoPoints(p(x1,y0),p(x1,y1)); ls.addByTwoPoints(p(x1,y1),p(x0,y1)); ls.addByTwoPoints(p(x0,y1),p(x0,y0))
def circle(sk,cx,cy,r): sk.sketchCurves.sketchCircles.addByCenterRadius(p(cx,cy),r)
def join_ext(root,sk,dist,op,name):
    f=root.features.extrudeFeatures.addSimple(sk.profiles.item(0),adsk.core.ValueInput.createByReal(dist),op); f.name=name; return f
def cut_ext(root,sk,dist,body,name):
    ex=root.features.extrudeFeatures; inp=ex.createInput(sk.profiles.item(0),adsk.fusion.FeatureOperations.CutFeatureOperation)
    inp.setDistanceExtent(False,adsk.core.ValueInput.createByReal(dist))
    parts=adsk.core.ObjectCollection.create(); parts.add(body); inp.participantBodies=parts
    f=ex.add(inp); f.name=name; return f
def export_case(des,root,top,right):
    mgr=des.exportManager
    stl_path='/Users/daiki/Projects/sage60/mechanical/gasket_v1/'+('sage60_right_tb_case_top.stl' if right else 'sage60_left_case_top.stl')
    step_path='/Users/daiki/Projects/sage60/mechanical/gasket_v1/'+('sage60_right_tb_case_complete.step' if right else 'sage60_left_case_complete.step')
    ok1=mgr.execute(mgr.createSTLExportOptions(top,stl_path)); ok2=mgr.execute(mgr.createSTEPExportOptions(step_path,root))
    return bool(ok1),bool(ok2)
def run(_context):
    app=adsk.core.Application.get(); out=[]
    for i in range(app.documents.count):
        doc=app.documents.item(i); des=adsk.fusion.Design.cast(doc.products.itemByProductType('DesignProductType'))
        if not des: continue
        root=des.rootComponent; bottom=None; top=None
        for b in root.bRepBodies:
            if b.name in ('LEFT_CASE_BOTTOM','RIGHT_TRACKBALL_CASE_BOTTOM'): bottom=b
            if b.name in ('LEFT_CASE_TOP','RIGHT_TRACKBALL_CASE_TOP'): top=b
        if not bottom: continue
        doc.activate()
        if bottom.name.startswith('LEFT'):
            opening=None
            for sk in root.sketches:
                if sk.name=='LEFT_CASE_BOTTOM_TOP_OPENING': opening=sk
            if top and opening:
                cut_ext(root,opening,0.35,top,'LEFT_CASE_TOP_OPENING'); opening.isVisible=False
            if top: top.name='LEFT_CASE_TOP'
            stl,step=export_case(des,root,top,False)
            out.append({'case':'left','top':top.name,'stl':stl,'completeStep':step})
        else:
            if not top:
                bb=bottom.boundingBox; x0=bb.minPoint.x; x1=bb.maxPoint.x; y0=bb.minPoint.y; y1=bb.maxPoint.y
                ix0=x0+0.30; ix1=x1-0.30; iy0=y0+0.30; iy1=y1-0.30
                pi=root.constructionPlanes.createInput(); pi.setByOffset(root.xYConstructionPlane,adsk.core.ValueInput.createByReal(1.07)); plane=root.constructionPlanes.add(pi)
                s=root.sketches.add(plane); s.name='RIGHT_CASE_TOP_OUTER'; rectangle(s,x0,y0,x1,y1); join_ext(root,s,0.35,adsk.fusion.FeatureOperations.NewBodyFeatureOperation,'RIGHT_TRACKBALL_CASE_TOP'); top=root.bRepBodies.item(root.bRepBodies.count-1); top.name='RIGHT_TRACKBALL_CASE_TOP'
                s2=root.sketches.add(plane); s2.name='RIGHT_CASE_TOP_OPENING'; rectangle(s2,ix0,iy0,ix1,iy1); cut_ext(root,s2,0.35,top,'RIGHT_CASE_TOP_OPENING'); s.isVisible=False; s2.isVisible=False
                sh=root.sketches.add(plane); sh.name='RIGHT_TOP_TRACKBALL_OPENING'; circle(sh,16.0995,-11.4535,1.85); cut_ext(root,sh,0.35,top,'RIGHT_TOP_TRACKBALL_CUT'); sh.isVisible=False
            stl,step=export_case(des,root,top,True)
            out.append({'case':'right','top':top.name,'stl':stl,'completeStep':step})
    print(json.dumps(out))
